#include <iostream>
#include <map>
#include <string>

struct Loud
{
    int value{};
    Loud(int v) : value{v} { std::cout << "  (constructed " << v << ")\n"; }
};

int main()
{
    std::map<std::string, int> m{};
    m["a"] = 1;
    auto [it, inserted]{m.insert({"a", 2})};
    std::cout << inserted << ' ' << it->second << '\n';
}
